import React, { forwardRef } from 'react';

import { TreeMapInternal } from './TreeMapInternal.js';
import { TreemapLegend } from './TreeMapLegend.js';
import { TreeMapOverlay } from './TreeMapOverlay/TreeMapOverlay.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import { ChartLayout } from '../../core/components/chart-layout/ChartLayout.js';
import { CATEGORICAL_LEGEND_SIZES } from '../../core/components/legend/categorical/constants.js';
import { useChartLegend } from '../context/ChartLegendContext.js';
import { useTreeMapData } from '../context/TreeMapDataContext.js';
import { getMetadata } from '../functions/get-metadata.js';
import { useTreeMapHandlers } from '../hooks/useTreeMapChartHandlers.js';

interface TreemapChartLayoutProps extends StylingProps {
  minNodeSize: number;
  height?: string | number;
  emptyState?: React.ReactNode;
  errorState:
    | React.ReactNode
    | ((errorMessage: string) => JSX.Element)
    | undefined;
  isEmpty: boolean;
  loading: boolean;
}

export const TreeMapChartLayout = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  TreemapChartLayoutProps
>((props, forwardedRef) => {
  const {
    minNodeSize,
    height,
    emptyState,
    errorState,
    isEmpty,
    loading,
    className,
    style,
  } = props;

  const { hidden, resizable, position, ratio = 25 } = useChartLegend();
  const { onLegendItemHover, onLegendItemClick } = useTreeMapHandlers();
  const data = useTreeMapData();

  const metadata = getMetadata(data.tree.children);

  const legendConfig = {
    orientation: hidden ? undefined : position,
    ratio,
    hidden,
    sizes: CATEGORICAL_LEGEND_SIZES,
  };

  return (
    <ChartLayout
      chartHeight={height}
      emptyState={emptyState}
      errorState={errorState}
      showLoader={loading}
      isEmpty={isEmpty}
      legendConfig={legendConfig}
      resizable={resizable}
      className={className}
      style={style}
    >
      <ChartLayout.Graph>
        <div style={{ position: 'relative' }}>
          <TreeMapInternal minNodeSize={minNodeSize} ref={forwardedRef} />
          <TreeMapOverlay metadata={metadata} />
        </div>
      </ChartLayout.Graph>
      <ChartLayout.Legend>
        {!hidden && (
          <TreemapLegend
            onHover={onLegendItemHover}
            onClick={onLegendItemClick}
          />
        )}
      </ChartLayout.Legend>
    </ChartLayout>
  );
});
